    {
        WorkspaceId = workspaceId,
        Key = RequirementScopeLayerDefaults.DefaultLayerKey,
        Order = 1,
        Name = "Layer 1",
        CreatedAtUtc = now,
        UpdatedAtUtc = now
    });
    await ctx.SaveChangesAsync(ct).ConfigureAwait(false);

